mapper.select:
SELECT b.customer_id, customer_name, phone, bill, max( bill_date ) AS bill_date, sum( pay_price ) AS pay_price, sum( voucher_amount ) AS voucher_amount, sum( balance_pay_amount ) AS balance_pay_amount, sum( arrears_amount ) AS arrears_amount, GROUP_CONCAT(b.id) AS billIds, CASE WHEN COUNT(b.id) = COUNT(ib.id) AND MAX(m.status) != 3 THEN 1 -- 如果账单数量一致且状态不为3，tag=1 ELSE 0 -- 否则 tag=0（包括状态为3的情况） END AS tag FROM sys_customer_bill b LEFT JOIN sys_customer c ON b.customer_id = c.id LEFT JOIN sys_invoice_bill ib ON b.id = ib.customer_bill_id AND ib.del_flag = 0 LEFT JOIN sys_invoice_manage m ON ib.invoice_manage_id = m.id -- 新增关联 AND m.del_flag = 0 -- 新增条件 WHERE b.del_flag = 0 and b.source_type != 12
and b.customer_id = #{param.customerId}
and STR_TO_DATE(b.bill, '%Y-%m') >= #{param.startMonth}
and STR_TO_DATE(b.bill, '%Y-%m') <= #{param.endMonth}
GROUP BY b.customer_id, b.bill ORDER BY tag ASC, bill DESC

SELECT customer_id, customer_name, phone, bill, max( bill_date ) AS bill_date, sum( pay_price ) AS pay_price, sum( voucher_amount ) AS voucher_amount, sum( balance_pay_amount ) AS balance_pay_amount, sum( arrears_amount ) AS arrears_amount FROM sys_customer_bill b LEFT JOIN sys_customer c ON b.customer_id = c.id WHERE b.del_flag = 0
and b.customer_id = #{param.customerId}
and STR_TO_DATE(b.bill, '%Y-%m') >= #{param.startMonth}
and STR_TO_DATE(b.bill, '%Y-%m') <= #{param.endMonth}
GROUP BY b.customer_id, b.bill ORDER BY bill DESC

SELECT b.id AS billId, b.customer_id, customer_name, phone, bill, bill_date AS bill_date, pay_price AS pay_price, voucher_amount AS voucher_amount, balance_pay_amount AS balance_pay_amount, arrears_amount AS arrears_amount, source_type AS source_type, CASE WHEN ib.id IS NOT NULL AND m.STATUS != 3 THEN 1 ELSE 0 END AS tag FROM sys_customer_bill b LEFT JOIN sys_customer c ON b.customer_id = c.id LEFT JOIN sys_invoice_bill ib ON b.id = ib.customer_bill_id AND ib.del_flag = 0 LEFT JOIN sys_invoice_manage m ON ib.invoice_manage_id = m.id -- 新增关联 AND m.del_flag = 0 -- 新增条件 WHERE b.del_flag = 0 and b.source_type != 12
and b.customer_id = #{param.customerId}
and b.bill_date >= #{param.startDay}
and b.bill_date <= #{param.endDay}
ORDER BY tag ASC, bill DESC

SELECT m.customer_id, c.customer_name, c.phone, m.id, m.application_time, t.invoice_title, t.invoice_type, m.invoice_number, m.invoice_price as amount, m.remark, m.status, m.proof, e.email, t.invoice_title as companyName, t.number as companyCode, t.address as companyAddress, t.contact as companyContactName, t.phone_number as companyContactPhone, t.contact_phone FROM sys_invoice_manage m LEFT JOIN sys_invoice_title t on m.invoice_title_id = t.id LEFT JOIN sys_invoice_email e ON m.invoice_email_id = e.id LEFT JOIN sys_customer c ON m.customer_id = c.id WHERE m.del_flag = 0
and m.customer_id = #{param.customerId}
and m.application_time >= #{param.startDay}
and m.application_time <= #{param.endDay}
ORDER BY m.application_time DESC

SELECT b.id as billId, customer_id, customer_name, phone, bill, bill_date AS bill_date, pay_price AS pay_price, credit_line_amount AS credit_line_amount, arrears_amount AS arrears_amount, source_type AS source_type, CASE WHEN ib.id IS NOT NULL THEN 1 ELSE 0 END AS tag FROM sys_customer_bill b LEFT JOIN sys_customer c ON b.customer_id = c.id LEFT JOIN sys_invoice_bill ib ON b.id = ib.customer_bill_id AND ib.del_flag = 0 WHERE b.del_flag = 0 and b.source_type = 12
and b.customer_id = #{param.customerId}
and b.bill_date >= #{param.startDay}
and b.bill_date <= #{param.endDay}
ORDER BY tag ASC, bill DESC

SELECT b.id as billId, b.customer_id, customer_name, phone, bill, bill_date AS bill_date, pay_price AS pay_price, voucher_amount AS voucher_amount, balance_pay_amount AS balance_pay_amount, arrears_amount AS arrears_amount, source_type AS source_type, CASE WHEN ib.id IS NOT NULL AND m.STATUS != 3 THEN 1 ELSE 0 END AS tag FROM sys_customer_bill b LEFT JOIN sys_customer c ON b.customer_id = c.id LEFT JOIN sys_invoice_bill ib ON b.id = ib.customer_bill_id AND ib.del_flag = 0 LEFT JOIN sys_invoice_manage m ON ib.invoice_manage_id = m.id -- 新增关联 AND m.del_flag = 0 -- 新增条件 WHERE b.del_flag = 0 AND (ib.id IS NULL OR m.status = 3)
and b.customer_id = #{param.customerId}
and b.bill_date >= #{param.startDay}
and b.bill_date <= #{param.endDay}
ORDER BY tag ASC, bill DESC
